// CreatePost is the resolver for the createPost field.
func (r *mutationResolver) CreatePost(ctx context.Context, input gqlmodel.CreatePostInput) (*gqlmodel.Post, error) {
	claims, err := requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	trimmedContent := strings.TrimSpace(input.Content)

	var numericParentID *int64
	if input.ParentID != nil && *input.ParentID != "" {
		parentID, err := decodeGraphID(ctx, "post", *input.ParentID)
		if err != nil {
			return nil, fmt.Errorf("invalid parent post id")
		}
		numericParentID = &parentID
	}

	ucMediaInputs, err := r.toMediaInputs(ctx, input.MediaInputs)
	if err != nil {
		return nil, err
	}

	post, err := r.CreatePostUseCase.Execute(ctx, model.CreatePostParam{
		UserID:   claims.ID,
		Content:  trimmedContent,
		ParentID: numericParentID,
	}, ucMediaInputs)
	if err != nil {
		return nil, err
	}

	// 返信先投稿者への通知は CreatePostUseCase 内で発行される。

	return toGraphPost(post), nil
}

