// AdminListConsents is the resolver for the adminListConsents field.
func (r *queryResolver) AdminListConsents(ctx context.Context, termsID string, limit *int32, offset *int32) (*gqlmodel.TermsConsentPage, error) {
	if _, err := requireAdminAuth(ctx); err != nil {
		return nil, err
	}
	tid, err := decodeGraphID(ctx, "terms", termsID)
	if err != nil {
		return nil, fmt.Errorf("invalid terms id")
	}
	consents, total, err := r.ListConsentsUseCase.Execute(ctx, tid, resolvePageQuery(ctx, limit, offset, defaultPageSize))
	if err != nil {
		return nil, err
	}

	userIDs := make([]int64, 0, len(consents))
	for _, c := range consents {
		userIDs = append(userIDs, c.UserID)
	}
	// 同意者台帳は管理者専用（このリゾルバの先頭で requireAdminAuth 済み）なので、
	// 連絡先込みで引く。TermsConsentRecord.user は UserAccount。
	users, err := r.GetUserAccountsByIDsUseCase.Execute(ctx, userIDs)
	if err != nil {
		return nil, err
	}
	userMap := make(map[int64]*model.UserAccount, len(users))
	for _, u := range users {
		userMap[u.ID] = u
	}

	items := make([]*gqlmodel.TermsConsentRecord, 0, len(consents))
	for _, c := range consents {
		u, ok := userMap[c.UserID]
		if !ok {
			continue
		}
		items = append(items, &gqlmodel.TermsConsentRecord{
			ID:          strconv.FormatInt(c.ID, 10),
			User:        toGraphUserAccount(u),
			ConsentedAt: c.ConsentedAt.Format(timeFormat),
		})
	}
	return &gqlmodel.TermsConsentPage{Items: items, Total: int32(total)}, nil
}

